// === Construit l'état pipeline (KPIs + top items + blocages) ===
const now = Date.now();
const run_id = 'adv_' + now;

const prospects = $('Lire review_queue').all().map(i => i.json);
const projects  = $('Lire project_queue').all().map(i => i.json);
const team      = $('Lire team_state').all().map(i => i.json);
const bcl       = $('Lire business_control').all().map(i => i.json);
const logs      = $('Lire logs (récents)').all().map(i => i.json);

function lower(v) { return String(v || '').toLowerCase(); }
function daysSince(iso) {
  if (!iso) return 999;
  const t = Date.parse(iso); if (Number.isNaN(t)) return 999;
  return Math.max(0, Math.floor((now - t) / 86400000));
}

// --- KPIs ---
const kpis = {
  prospects_total: prospects.length,
  prospects_pending: prospects.filter(p => lower(p.status) === 'queued_for_review').length,
  prospects_in_review: prospects.filter(p => lower(p.status) === 'queued_for_review' && !p.human_decision).length,
  prospects_drafted: prospects.filter(p => lower(p.status) === 'drafted_in_gmail').length,
  prospects_replied_interested: prospects.filter(p => lower(p.reply_category) === 'interested').length,
  prospects_replied_not_interested: prospects.filter(p => lower(p.reply_category) === 'not_interested').length,
  projects_active: projects.filter(p => ['new', 'in_progress'].includes(lower(p.status))).length,
  projects_blocked: projects.filter(p => lower(p.status) === 'blocked').length,
  projects_due_soon: projects.filter(p => p.deadline && daysSince(p.deadline) >= -7 && daysSince(p.deadline) < 0).length,
  high_priority_count: 0,
  critical_count: 0
};

// --- Top items depuis business_control (dernier run WF7) ---
const lastWF7 = bcl
  .filter(b => b.source_workflow === 'WF7')
  .sort((a, b) => String(b.ts).localeCompare(String(a.ts)));
const lastRunIds = [...new Set(lastWF7.map(b => b.run_id))].slice(0, 1);
const topItems = lastWF7
  .filter(b => lastRunIds.includes(b.run_id))
  .slice(0, 10)
  .map(b => ({
    item_type: b.item_type,
    item_id: b.item_id,
    title: b.title,
    priority_level: b.priority_level,
    score_raw: Number(b.priority_score) || 0,
    summary: b.recommendation
  }));
kpis.high_priority_count = topItems.filter(t => t.priority_level === 'high').length;
kpis.critical_count      = topItems.filter(t => t.priority_level === 'critical').length;

// --- Team state ---
const teamState = team.map(t => ({
  name: t.name,
  role: t.role,
  current_load_pct: Number(t.current_load_pct) || 0,
  weekly_capacity_hours: Number(t.weekly_capacity_hours) || 35,
  current_committed_hours: Number(t.current_committed_hours) || 0,
  unavailable_days: String(t.unavailable_days || '').split(',').map(s => s.trim()).filter(Boolean)
}));

// --- Blocages récents (logs level=error sur 7 derniers jours) ---
const recentBlockages = logs
  .filter(l => lower(l.level) === 'error' && daysSince(l.ts) <= 7)
  .slice(-15)
  .map(l => ({
    prospect_id: l.prospect_id,
    phase: l.phase,
    message: String(l.message || '').slice(0, 200)
  }));

// --- Période ISO week label ---
const d = new Date();
const onejan = new Date(d.getFullYear(), 0, 1);
const week = Math.ceil((((d - onejan) / 86400000) + onejan.getDay() + 1) / 7);
const snapshot_period = `${d.getFullYear()}-W${String(week).padStart(2, '0')}`;

return [{
  json: {
    run_id,
    snapshot_period,
    kpis,
    team_state: teamState,
    top_items: topItems,
    recent_blockages: recentBlockages
  }
}];

