// Parse advisor + persiste : 1 ligne business_control (synthèse) + 1 snapshot KPI
const llm = $json;
let advisor = {};
try {
  const c = llm && llm.choices && llm.choices[0] && llm.choices[0].message && llm.choices[0].message.content;
  if (c) advisor = JSON.parse(c);
} catch (e) {
  advisor = { _llm_error: String(e && e.message || e) };
}

const ctx = $('Build BUSINESS_STATE').first().json;
const now = new Date().toISOString();

const bclRow = {
  id: 'bcl_' + Date.now() + '_advisor',
  ts: now,
  run_id: ctx.run_id,
  source_workflow: 'WF8',
  item_type: 'ops',
  item_id: ctx.snapshot_period,
  title: `Synthèse Business Advisor — ${ctx.snapshot_period}`,
  recommendation: (advisor.weekly_priorities || []).slice(0, 3).join(' | ') || (advisor._llm_error || 'pas de reco'),
  recommended_action: 'review',
  priority_score: '',
  priority_level: (ctx.kpis.critical_count > 0 ? 'critical' : (ctx.kpis.high_priority_count > 0 ? 'high' : 'medium')),
  expected_impact: 'high',
  effort_level: 'low',
  assigned_to: 'Arsène+Kentin',
  requires_human_validation: 'true',
  decision_status: 'pending',
  decided_by: '',
  decided_at: '',
  notes: JSON.stringify({
    weekly_risks: advisor.weekly_risks || [],
    strategic_notes: advisor.strategic_notes || [],
    team_balance: advisor.team_balance || {},
    leads_to_push: advisor.leads_to_push || [],
    leads_to_drop: advisor.leads_to_drop || [],
    projects_to_accelerate: advisor.projects_to_accelerate || [],
    projects_to_slow_down: advisor.projects_to_slow_down || [],
    open_questions: advisor.open_questions_for_team || []
  })
};

const kpiRow = {
  ts: now,
  run_id: ctx.run_id,
  period: ctx.snapshot_period,
  prospects_total: ctx.kpis.prospects_total,
  prospects_pending: ctx.kpis.prospects_pending,
  prospects_in_review: ctx.kpis.prospects_in_review,
  prospects_drafted: ctx.kpis.prospects_drafted,
  prospects_replied_interested: ctx.kpis.prospects_replied_interested,
  prospects_replied_not_interested: ctx.kpis.prospects_replied_not_interested,
  projects_active: ctx.kpis.projects_active,
  projects_blocked: ctx.kpis.projects_blocked,
  projects_due_soon: ctx.kpis.projects_due_soon,
  team_load_arsene_pct: (ctx.team_state.find(t => String(t.name).toLowerCase().startsWith('ars')) || {}).current_load_pct || '',
  team_load_kentin_pct: (ctx.team_state.find(t => String(t.name).toLowerCase().startsWith('ken')) || {}).current_load_pct || '',
  high_priority_count: ctx.kpis.high_priority_count,
  critical_count: ctx.kpis.critical_count,
  notes: JSON.stringify((advisor.weekly_priorities || []).slice(0, 5))
};

return [
  { json: { _target: 'business_control', ...bclRow } },
  { json: { _target: 'kpi_snapshots', ...kpiRow } }
];
